(function(){
    document.querySelectorAll('.probe-mark').forEach(e=>e.remove());
    const mark=(sel,color,label)=>{const e=document.querySelector(sel);if(!e)return null;const r=e.getBoundingClientRect();const d=document.createElement('div');d.className='probe-mark';d.style.cssText='position:fixed;z-index:99999;pointer-events:none;border:3px solid '+color+';left:'+r.left+'px;top:'+r.top+'px;width:'+r.width+'px;height:'+r.height+'px;';const t=document.createElement('div');t.textContent=label;t.style.cssText='position:absolute;left:0;top:-22px;background:'+color+';color:#fff;font:12px/18px monospace;padding:0 6px;border-radius:3px;white-space:nowrap;';d.appendChild(t);document.body.appendChild(d);return {l:Math.round(r.left),t:Math.round(r.top),r:Math.round(r.right),b:Math.round(r.bottom)};};
    const a=mark('[data-im="chat-panel"]','#e879bd','聊天面板 '+Math.round(document.querySelector('[data-im="chat-panel"]').getBoundingClientRect().left)+'-'+Math.round(document.querySelector('[data-im="chat-panel"]').getBoundingClientRect().right));
    const b=mark('[data-im="batch-list"]','#3fa9f5','批量列表');
    const tb=mark('[data-im="board-toolbar"]','#7ed321','底部工具栏');
    const inter=(x,y)=>{if(!x||!y)return 0;return Math.max(0,Math.min(x.r,y.r)-Math.max(x.l,y.l))*Math.max(0,Math.min(x.b,y.b)-Math.max(x.t,y.t));};
    const s=document.createElement('div');s.className='probe-mark';s.textContent='聊天×批量相交 = '+inter(a,b)+' px²';s.style.cssText='position:fixed;z-index:99999;left:16px;top:8px;background:#111;color:#fff;font:14px/22px monospace;padding:2px 10px;border-radius:4px;';
    document.body.appendChild(s);
    return JSON.stringify({chat:a,batch:b,toolbar:tb,inter:inter(a,b)});
  })()
